-- Etapa 5. Leitura; escopos geral e delivered se sobrepõem.
WITH b AS (SELECT x.order_id,x.order_status order_status,dt.dia dia_compra,date_trunc('month',dt.dia)::date mes,l.customer_state uf,l.customer_city cidade,l.membro_tipo localizacao_tipo,x.order_item_id,x.price,x.freight_value,p.product_id,p.product_category_name,p.product_category_name_english product_category_name_english,v.seller_id FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario dt ON dt.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk LEFT JOIN gold.dim_produtos p ON p.produto_sk=x.produto_sk LEFT JOIN gold.dim_vendedores v ON v.vendedor_sk=x.vendedor_sk), a AS (SELECT 'geral'::text escopo,b.* FROM b UNION ALL SELECT 'delivered',b.* FROM b WHERE order_status='delivered') SELECT escopo,localizacao_tipo,uf,cidade,count(*) linhas,count(DISTINCT order_id) pedidos,sum(price) price,sum(freight_value) freight_value FROM a GROUP BY escopo,localizacao_tipo,uf,cidade;
